DO $$ DECLARE pol text; expression text; BEGIN FOREACH pol IN ARRAY ARRAY['enforce uploaded photo formats and sizes','enforce updated photo formats and sizes'] LOOP SELECT pg_get_expr(polwithcheck,polrelid) INTO expression FROM pg_policy WHERE polname=pol AND polrelid='storage.objects'::regclass; expression:=replace(expression,'(metadata IS NULL)','((metadata ->> ''size'') IS NULL)'); EXECUTE format('ALTER POLICY %I ON storage.objects WITH CHECK (%s)',pol,expression); END LOOP; END $$;